// Segredo compartilhado com o Worker do Cloudflare (env N8N_NOTION_WEBHOOK_SECRET).
// Troque 'TROQUE_PELO_SEGREDO' pelo mesmo valor configurado no Worker (e no 07).
const SECRET = 'TROQUE_PELO_SEGREDO';

const item = $input.first().json || {};
const headers = item.headers || {};

const headerName = Object.keys(headers).find((k) => k.toLowerCase() === 'x-radar-secret');
if (!headerName || headers[headerName] !== SECRET) {
  throw new Error('x-radar-secret invalido ou ausente');
}

return [{ json: { ok: true } }];

// Lê as páginas do database "Radar Mobiliza PE" (dado cru da API do Notion) e
// normaliza para as chaves usadas no envio (07/form). Devolve também:
//  - devolutiva: texto da propriedade "Devolutiva da campanha"
//  - outros: demais propriedades não consumidas (para o drawer)

const plainText = (arr) =>
  Array.isArray(arr) ? arr.map((t) => (t && t.plain_text) || '').join('') : '';

const valueOf = (prop) => {
  if (!prop) return '';
  const t = prop.type;
  if (t === 'title' || t === 'rich_text') return plainText(prop[t]);
  if (t === 'select') return (prop.select && prop.select.name) || '';
  if (t === 'status') return (prop.status && prop.status.name) || '';
  if (t === 'people')
    return (prop.people || [])
      .map((p) => (p && p.name) || '')
      .filter(Boolean)
      .join(', ');
  if (t === 'phone_number') return prop.phone_number || '';
  if (t === 'date') return (prop.date && (prop.date.start || '')) || '';
  if (t === 'url') return prop.url || '';
  if (t === 'email') return prop.email || '';
  if (t === 'number') return prop.number != null ? String(prop.number) : '';
  if (t === 'checkbox') return prop.checkbox != null ? (prop.checkbox ? 'Sim' : 'Não') : '';
  return '';
};

const CONSUMED = new Set([
  'O que chegou',
  'O que a pessoa disse',
  'Área',
  'Precisa de retorno',
  'Responsável pelo contato',
  'Pessoa',
  'Telefone',
  'Data',
  'Urgência',
  'O que a gente fez',
  'Status',
  'Fonte',
  'Cidade',
  'Sessão responsável pelo contato',
  'Devolutiva da campanha',
]);

const pages = $input
  .all()
  .map(({ json }) => json)
  .filter((p) => p && !p.archived);

const rows = pages.map((page) => {
  const props = page.properties || {};
  const tituloProp = Object.values(props).find((p) => p && p.type === 'title');
  const g = (name) => valueOf(props[name]);

  const outros = Object.keys(props)
    .filter((key) => !CONSUMED.has(key) && props[key] && props[key].type !== 'title')
    .map((key) => ({ key, value: valueOf(props[key]) }))
    .filter((o) => o.value.trim() !== '');

  const respProp = props['Responsável pelo contato'];
  const respPeople = respProp && respProp.type === 'people' ? respProp.people : [];

  return {
    page_id: page.id,
    url: page.url || '',
    titulo: plainText((tituloProp && tituloProp.title) || []) || 'Sem título',
    o_que_disse: g('O que a pessoa disse'),
    area: g('Área'),
    precisa_retorno: g('Precisa de retorno'),
    responsavel: g('Responsável pelo contato'),
    responsavel_id: (respPeople[0] && respPeople[0].id) || '',
    pessoa: g('Pessoa'),
    telefone: g('Telefone'),
    data: g('Data'),
    urgencia: g('Urgência'),
    o_que_fizemos: g('O que a gente fez'),
    status: g('Status'),
    fonte: g('Fonte'),
    cidade: g('Cidade'),
    sessao_responsavel: g('Sessão responsável pelo contato'),
    devolutiva: g('Devolutiva da campanha'),
    outros,
  };
});

return [{ json: { rows } }];
